mapper.select:
/***selectOneUdtFile***/ SELECT FILE_ID ,FILE_SN ,FILE_DIR ,FILE_SIZE ,FILE_ORG_NM ,FILE_SAVE_NM ,FILE_EXT ,FILE_TYPE ,TO_CHAR(TO_TIMESTAMP(reg_dt,'YYYYMMDDHH24MISS'),'YYYY.MM.DD HH24:MI:SS')AS REG_DT ,TO_CHAR(TO_TIMESTAMP(UPDT_DT,'YYYYMMDDHH24MISS'),'YYYY.MM.DD HH24:MI:SS')AS UPDT_DT FROM UDT_FILE WHERE FILE_ID=#{fileId}::Integer
AND FILE_SN=#{fileSn}::Integer
;

mapper.insert:
/***insertUdtFile***/
INSERT INTO UDT_FILE(
	FILE_SN, FILE_DIR, FILE_SIZE, FILE_ORG_NM, FILE_SAVE_NM, FILE_EXT, FILE_TYPE)
VALUES (

		   	SELECT (COALESCE(MAX(FILE_SN),0)+1) AS FILE_SN FROM UDT_FILE WHERE FILE_ID =#{fileId}


		  	1

		 ,#{saveUploadPath}
		 ,#{fileSize}
		 ,#{originFilename}
		 ,#{saveFileName}
		 ,#{extName}
		 ,#{fileType}
	    );

mapper.select:
SELECT CAST(COUNT(A.FILE_ID) OVER() AS INTEGER) AS totcnt ,(EXISTS(SELECT 1 FROM TBINFO_SRC_DATA WHERE A.FILE_ID=LATELY_FILE_ID)) AS IS_LATELY ,A.FILE_ID ,A.SRC_TB_EN_NM ,TO_CHAR(A.TIME_STMP,'YYYY.MM.DD HH24:MI:SS')AS TIME_STMP ,B.FILE_ORG_NM ,B.FILE_SIZE ,REPLACE(B.FILE_EXT,'.','') AS FILE_EXT ,CASE WHEN B.FILE_TYPE = 'UDT_FTP' THEN 'SFTP 수신파일' WHEN B.FILE_TYPE = 'UDT_ULD' THEN '관리자웹 업로드' ELSE B.FILE_TYPE END AS FILE_TYPE FROM TBINFO_SRC_DATA_FILE_HST A, UDT_FILE B WHERE A.SRC_TB_EN_NM=#{srcTbEnNm} AND A.FILE_ID=B.FILE_ID
AND B.FILE_ORG_NM LIKE '%' || #{fileNm} || '%'
AND TO_CHAR(A.TIME_STMP,'YYYYMMDD') BETWEEN #{insertStartDt} AND #{insertEndDt}
ORDER BY A.TIME_STMP DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.update:
/***"updateSrcTableInfo"***/
UPDATE TBINFO_SRC_DATA SET
	LATELY_TIMESTMP=#{timeStmp}
	,LATELY_FILE_ID=#{fileId}
	,LATELY_ROW_CNT=#{rowCnt}
	,UPDT_DT=to_char(now(),'YYYYMMDDHH24MISS')
WHERE UPPER(SRC_TB_EN_NM)=UPPER(#{srcTbNm});

mapper.insert:
/***"updateSrcTableInfo"***/
INSERT INTO PUBLIC.TBINFO_SRC_DATA_FILE_HST(
SRC_TB_EN_NM, FILE_ID, TIME_STMP)
VALUES (#{srcTbNm}, #{fileId}, #{timeStmp});
